Tool response:
Tool: update_stop_status
Description: Update Stop Status
Parameters:
    {
      "type": "object",
      "properties": {
        "route_code": {
          "type": "string",
          "description": "Unique identifier for the route",
          "title": "Route Code"
        },
        "stop_code": {
          "type": "string",
          "description": "Unique identifier for the stop",
          "title": "Stop Code"
        },
        "new_status": {
          "type": "string",
          "title": "New Status",
          "description": "New status to set for the stop (must be 'returned')"
        },
        "reason_code": {
          "type": "string",
          "title": "Reason Code",
          "description": "Reason code for the status change (e.g., 'DAMG-07')"
        },
        "return_timestamp": {
          "type": "string",
          "title": "Return Timestamp",
          "description": "Timestamp when the return occurred in ISO format"
        }
      },
      "required": [
        "route_code",
        "stop_code",
        "new_status",
        "reason_code",
        "return_timestamp"
      ]
    }

Tool response:
Tool: create_maintenance_alert
Description: Create Maintenance Alert
Parameters:
    {
      "type": "object",
      "properties": {
        "vehicle_code": {
          "type": "string",
          "title": "Vehicle Code",
          "description": "Vehicle code for which to create the alert (e.g., 'VL-9876-TRN')"
        },
        "alert_type": {
          "type": "string",
          "title": "Alert Type",
          "description": "Type of maintenance alert (e.g., 'battery_low')"
        },
        "description": {
          "type": "string",
          "title": "Description",
          "description": "Description of the maintenance issue"
        },
        "severity": {
          "type": "string",
          "title": "Severity",
          "description": "Severity level of the alert (low, medium, high, critical)"
        }
      },
      "required": [
        "vehicle_code",
        "alert_type",
        "description",
        "severity"
      ]
    }
